create table sales.order_change_requests(id uuid primary key default gen_random_uuid(),order_id uuid not null references sales.orders(id)on delete restrict,request_kind text not null check(request_kind in('correction','return-refund')),requested_change text not null,status_key text not null default'open'check(status_key in('open','acknowledged','handed-off','closed')),requested_at timestamptz not null default statement_timestamp(),resolved_at timestamptz,resolved_by uuid,resolution_note text,constraint requested_change_present check(btrim(requested_change)<>''));
create trigger order_change_requests_prevent_delete before delete on sales.order_change_requests for each row execute function sales.prevent_transition_mutation();alter table sales.order_change_requests enable row level security;revoke all on sales.order_change_requests from public,anon,authenticated;grant all on sales.order_change_requests to service_role;
create or replace function public.request_order_change(p_order_reference text,p_phone text,p_request text)returns text language plpgsql security definer set search_path=''as $$declare o sales.orders%rowtype;kind text;begin if nullif(btrim(p_request),'')is null then raise exception'Request details are required.';end if;select orders.*into o from sales.orders orders join sales.order_addresses a on a.order_id=orders.id where orders.external_reference=upper(btrim(p_order_reference))and regexp_replace(a.phone,'[^0-9]+','','g')=regexp_replace(p_phone,'[^0-9]+','','g');if o.id is null then raise exception'Order details could not be verified.';end if;kind:=case when o.current_state_key in('shipped','delivered','completed','returned')then'return-refund'else'correction'end;insert into sales.order_change_requests(order_id,request_kind,requested_change)values(o.id,kind,btrim(p_request));if kind='correction'then insert into sales.order_review_cases(order_id,review_type_key,internal_note)values(o.id,'configured-risk','Customer-visible correction requested; revalidation and confirmation required.')on conflict do nothing;end if;insert into notifications.outbox(event_key,audience_key,order_id,payload)values('order-'||kind||'-requested','admin',o.id,jsonb_build_object('requestKind',kind));return kind;end$$;revoke all on function public.request_order_change(text,text,text)from public;grant execute on function public.request_order_change(text,text,text)to anon,authenticated;
create or replace function public.admin_order_change_queue()returns jsonb language sql stable security definer set search_path=''as $$select case when public.is_reyon_admin()then coalesce(jsonb_agg(jsonb_build_object('id',r.id,'orderNumber',o.external_reference,'orderState',o.current_state_key,'kind',r.request_kind,'request',r.requested_change,'status',r.status_key)order by r.requested_at),'[]'::jsonb)else null end from sales.order_change_requests r join sales.orders o on o.id=r.order_id where r.status_key in('open','acknowledged')$$;revoke all on function public.admin_order_change_queue()from public,anon;grant execute on function public.admin_order_change_queue()to authenticated;
create or replace function public.admin_acknowledge_order_change(p_request_id uuid,p_note text)returns void language plpgsql security definer set search_path=''as $$begin if public.reyon_admin_role()is null then raise exception'Administrator access required.';end if;if nullif(btrim(p_note),'')is null then raise exception'Internal note is required.';end if;update sales.order_change_requests set status_key=case when request_kind='return-refund'then'handed-off'else'acknowledged'end,resolved_at=case when request_kind='return-refund'then statement_timestamp()else null end,resolved_by=auth.uid(),resolution_note=btrim(p_note)where id=p_request_id and status_key='open';if not found then raise exception'Open request not found.';end if;end$$;revoke all on function public.admin_acknowledge_order_change(uuid,text)from public,anon;grant execute on function public.admin_acknowledge_order_change(uuid,text)to authenticated;
